UPDATE pack_content.brand
SET narrative_json = $narrative${"version":1,"brandCode":"trading","coreStatement":"Người Giữ Vốn teaches risk management and trading discipline so people keep their capital first. Education only: no signals, no recommendations, no profit promises, no exchange promotion.","primaryAudience":["Trader cá nhân mới và trung cấp","Người từng cháy hoặc lỗ tài khoản"],"secondaryAudience":["Người đang cân nhắc bắt đầu giao dịch"],"territories":[{"id":"trading.core.risk-management","name":"Quản trị rủi ro và vốn","type":"core","description":"Định cỡ vị thế, dừng lỗ, đòn bẩy, ký quỹ, giới hạn lỗ, chi phí giao dịch, gap, kịch bản xấu nhất.","whyItBelongs":"Đây là xương sống của kênh: giữ vốn trước lợi nhuận.","audience":"Trader cá nhân mới và trung cấp","examples":["Cách tính khối lượng lệnh theo mức rủi ro mỗi lệnh.","Vì sao đặt điểm dừng lỗ trước khi vào lệnh."],"boundaries":["Không đưa điểm vào lệnh hay mục tiêu giá cụ thể."],"priority":1},{"id":"trading.core.discipline-psychology","name":"Kỷ luật và tâm lý giao dịch","type":"core","description":"FOMO, trả thù thị trường, thắng rồi ngáo, gồng lỗ, cháy tài khoản và cách nhận diện sớm.","whyItBelongs":"Phần lớn thua lỗ đến từ hành vi chứ không phải từ chỉ báo.","audience":"Trader cá nhân mới và trung cấp","examples":["FOMO làm bạn vào lệnh quá lớn như thế nào.","Sau chuỗi thua nên dừng lại làm gì."],"boundaries":["Không đổ lỗi cho cá mập hay sàn mà bỏ qua phần của người giao dịch."],"priority":2},{"id":"trading.core.journal-process","name":"Nhật ký, kế hoạch và quy trình","type":"core","description":"Nhật ký giao dịch, thống kê, kế hoạch bằng văn bản, quy trình trước-trong-sau lệnh, backtest đúng cách.","whyItBelongs":"Biến kỷ luật thành thói quen đo được.","audience":"Trader cá nhân mới và trung cấp","examples":["Nhật ký giao dịch một trang gồm những gì.","Backtest đúng cách và cái bẫy quá khớp."],"boundaries":["Không khoe kết quả lãi hay số dư tài khoản."],"priority":3},{"id":"trading.supporting.foundations","name":"Nền tảng thị trường và thuật ngữ","type":"supporting","description":"Thuật ngữ nền tảng, sự thật về nghề trade, vốn sống và vốn giao dịch, trader hay con bạc.","whyItBelongs":"Người mới cần ngôn ngữ chung trước khi học quản trị rủi ro.","audience":"Trader cá nhân mới và trung cấp","examples":["Pip lot spread nghĩa là gì và vì sao quan trọng với rủi ro."],"boundaries":["Không dạy cách làm giàu nhanh."],"priority":10},{"id":"trading.supporting.fraud-awareness","name":"Nhận biết lừa đảo đầu tư","type":"supporting","description":"Chiêu show tài khoản, quỹ trade online, trung tâm dạy đầu tư, đa cấp, ủy thác. Làm theo mối nguy - cơ chế - dấu hiệu - việc nên làm.","whyItBelongs":"Bảo vệ vốn của người xem là cốt lõi của kênh.","audience":"Trader cá nhân mới và trung cấp","examples":["Dấu hiệu nhận biết nhóm đầu tư hứa lãi cố định."],"boundaries":["Không nêu tên hãng hay cá nhân cụ thể."],"priority":11},{"id":"trading.supporting.markets","name":"Từng thị trường","type":"supporting","description":"Forex, vàng, dầu, hợp đồng tương lai, tiền ảo, chứng khoán, tài chính chung: là gì, rủi ro đặc thù, khung pháp lý, cái cần theo dõi.","whyItBelongs":"Người xem giao dịch nhiều thị trường và cần biết rủi ro riêng của từng nơi.","audience":"Trader cá nhân mới và trung cấp","examples":["Rủi ro đặc thù khi giao dịch vàng quanh ngày công bố tin lớn."],"boundaries":["Không dự đoán giá và không khuyến nghị mã hay đồng coin cụ thể."],"priority":12},{"id":"trading.supporting.legal-context","name":"Khung pháp lý hiện hành","type":"supporting","description":"Quy định hiện hành cho forex qua broker nước ngoài, thí điểm tài sản mã hóa, khuyến nghị chứng khoán. Luôn có nguồn và ngày.","whyItBelongs":"Người xem cần biết điều gì được phép để không vi phạm.","audience":"Trader cá nhân mới và trung cấp","examples":["Thí điểm thị trường tài sản mã hóa theo Nghị quyết 5/2025/NQ-CP nghĩa là gì."],"boundaries":["Không dạy lách luật hay thuế."],"priority":13},{"id":"trading.adjacent.technical-concepts","name":"Phân tích kỹ thuật dạng khái niệm","type":"adjacent","description":"Công cụ đo cái gì, hạn chế gì, khi nào không dùng. Chỉ ở mức khái niệm.","whyItBelongs":"Hỗ trợ hiểu thị trường nhưng không được thành hướng dẫn vào lệnh.","audience":"Trader cá nhân mới và trung cấp","examples":["RSI đo cái gì và vì sao không phải tín hiệu bán."],"boundaries":["Không làm video cách vào lệnh theo chỉ báo."],"priority":20},{"id":"trading.adjacent.personal-finance","name":"Tài chính cá nhân","type":"adjacent","description":"Lạm phát ăn mòn tiền gửi, quỹ khẩn cấp, chia vốn, vì sao người mới thua trong năm đầu.","whyItBelongs":"Liên quan khi giúp người xem tách tiền sống khỏi tiền giao dịch.","audience":"Trader cá nhân mới và trung cấp","examples":["Quỹ khẩn cấp phải có trước khi lấy một đồng đi giao dịch."],"boundaries":["Không tư vấn sản phẩm tài chính cụ thể."],"priority":21},{"id":"trading.adjacent.assistant-experience","name":"Trải nghiệm và Trợ lý","type":"adjacent","description":"Nhật ký trải nghiệm có quy trình và demo tính năng Trợ lý khi đã xác nhận tính năng thật.","whyItBelongs":"Cho thấy kỷ luật được áp dụng thế nào trong thực tế.","audience":"Trader cá nhân mới và trung cấp","examples":["Mình kể một lệnh nhỏ và điều học được từ sai sót."],"boundaries":["Không khoe lãi và không quảng bá tính năng chưa có thật."],"priority":22},{"id":"trading.off.signals","name":"Tín hiệu và kèo vào lệnh","type":"off-brand","description":"Đưa tín hiệu mua bán, điểm vào ra lệnh, kèo.","whyItBelongs":"Sai quy định và đi ngược định vị giữ vốn.","audience":"—","examples":["Tín hiệu vàng hôm nay nên mua ở mức nào."],"boundaries":["Không."],"priority":90},{"id":"trading.off.recommendations","name":"Khuyên mã cụ thể","type":"off-brand","description":"Khuyên mua hoặc bán một mã cổ phiếu hay đồng coin cụ thể.","whyItBelongs":"Khuyến nghị chứng khoán khi chưa có giấy phép bị xử phạt.","audience":"—","examples":["Cổ phiếu tiềm năng tuần này nên gom."],"boundaries":["Không."],"priority":91},{"id":"trading.off.promotion","name":"Quảng cáo sàn và link giới thiệu","type":"off-brand","description":"Quảng cáo sàn, broker, mã giới thiệu, ưu đãi phí.","whyItBelongs":"Kênh không bán sàn và không nhận hoa hồng giới thiệu.","audience":"—","examples":["Đăng ký sàn qua link này để được giảm phí."],"boundaries":["Không."],"priority":92},{"id":"trading.off.profit-promises","name":"Hứa hẹn lợi nhuận","type":"off-brand","description":"Hứa lãi chắc chắn, x2 tài khoản, làm giàu nhanh.","whyItBelongs":"Sai quy định và gây hại cho người xem.","audience":"—","examples":["Làm theo cách này gấp đôi tài khoản trong một tháng."],"boundaries":["Không."],"priority":93},{"id":"trading.off.politics","name":"Chính trị","type":"off-brand","description":"Bình luận chính trị.","whyItBelongs":"Ngoài định vị của kênh.","audience":"—","examples":["Bình luận chính trị trong nước hôm nay."],"boundaries":["Không."],"priority":94}],"hardBoundaries":["Không tín hiệu hay kèo","Không khuyên mua bán mã cụ thể","Không quảng cáo sàn hay link giới thiệu","Không hứa hẹn lợi nhuận","Mọi số liệu và quy định phải có nguồn và ngày"],"mustNotBecome":"Một nhóm kèo hay kênh quảng cáo sàn giao dịch.","guard":{"offBrandIf":["tín hiệu mua","tín hiệu bán","tín hiệu vào lệnh","nên mua","nên bán","khuyên mua","khuyên bán","kèo thơm","mã giới thiệu","link đăng ký sàn","làm giàu nhanh","chắc chắn lãi","x2 tài khoản"],"unlessAlso":["cảnh báo","lừa đảo","dấu hiệu","vì sao không","tại sao không","sai lầm","đừng"]}}$narrative$::jsonb,
    updated_at = NOW()
WHERE code = 'trading';
